package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for CommandLine#getParsedOptionValue(String, T)
 */
public class CommandLine_GetParsedOptionValue_Test {

    /**
     * Testable subclass that captures calls to getParsedOptionValue(Option, T).
     * We override the public overload so calls from getParsedOptionValue(String, T)
     * (which delegates to the Option overload) can be observed.
     */
    static class TestableCommandLine extends CommandLine {
        volatile Option capturedOption;
        volatile Object capturedDefault;

        TestableCommandLine() {
            super(); // calls protected no-arg constructor
        }

        @Override
        public <T> T getParsedOptionValue(final Option option, final T defaultValue) {
            this.capturedOption = option;
            this.capturedDefault = defaultValue;
            // Simply return the provided defaultValue to make assertions straightforward.
            return defaultValue;
        }
    }

    // helper to add an Option instance into the private 'options' list of CommandLine
    private static void addOptionToCommandLine(final CommandLine cmd, final Option opt) throws Exception {
        final Field optionsField = CommandLine.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        @SuppressWarnings("unchecked")
        final List<Option> options = (List<Option>) optionsField.get(cmd);
        options.add(opt);
    }

    @Test
    public void delegatesToOptionOverload_whenShortOptionNameMatches() throws Exception {
        final TestableCommandLine cmd = new TestableCommandLine();
        // Create an option with short opt "a" and long opt "alpha"
        final Option opt = new Option("a", "alpha", false, "desc");
        addOptionToCommandLine(cmd, opt);

        final String defaultVal = "defaultVal";
        final String result = cmd.getParsedOptionValue("a", defaultVal);

        // returned value should be the default we returned from the overridden method
        assertEquals(defaultVal, result);
        // the overridden method should have been invoked with the Option instance we placed into the list
        assertSame(opt, cmd.capturedOption);
        assertEquals(defaultVal, cmd.capturedDefault);
    }

    @Test
    public void delegatesToOptionOverload_whenLongOptionNameMatches() throws Exception {
        final TestableCommandLine cmd = new TestableCommandLine();
        final Option opt = new Option("a", "alpha", false, "desc");
        addOptionToCommandLine(cmd, opt);

        final Integer defaultVal = Integer.valueOf(42);
        final Integer result = cmd.getParsedOptionValue("alpha", defaultVal);

        assertEquals(defaultVal, result);
        assertSame(opt, cmd.capturedOption);
        assertEquals(defaultVal, cmd.capturedDefault);
    }

    @Test
    public void delegatesToOptionOverload_whenNoOptionFound_passesNullOption() throws Exception {
        final TestableCommandLine cmd = new TestableCommandLine();
        // don't add any options

        final String defaultVal = "notFoundDefault";
        final String result = cmd.getParsedOptionValue("nonexistent", defaultVal);

        assertEquals(defaultVal, result);
        // resolveOption should have returned null and the overloaded method should receive null
        assertNull(cmd.capturedOption);
        assertEquals(defaultVal, cmd.capturedDefault);
    }

    @Test
    public void delegatesToOptionOverload_whenOptionNameHasLeadingHyphens() throws Exception {
        final TestableCommandLine cmd = new TestableCommandLine();
        final Option opt = new Option("x", "xlong", false, "desc");
        addOptionToCommandLine(cmd, opt);

        final String defaultVal = "hyphenDefault";
        // pass name with leading hyphens; resolveOption strips leading hyphens before matching
        final String result = cmd.getParsedOptionValue("--xlong", defaultVal);

        assertEquals(defaultVal, result);
        assertSame(opt, cmd.capturedOption);
        assertEquals(defaultVal, cmd.capturedDefault);
    }
}

